class Painter:
 def __init__(self):
  self.pos=np.array(r.get_obs(cameras=[]).meta['proprio']['now'][7:10]);self.rows=[]
  self.wells=np.array(json.load(open('/app/output/wells.json')))
 def to(self,p,speed=.12,hold=0):
  p=np.array(p);n=max(1,int(np.ceil(np.linalg.norm(p-self.pos)/(speed*.05))))
  self.rows.extend([list(self.pos+(p-self.pos)*i/n)+Q for i in range(1,n+1)])
  self.rows.extend([list(p)+Q]*int(hold*20));self.pos=p
 def flush(self):
  while self.rows:
   chunk=self.rows[:190];self.rows=self.rows[190:];res=submit(chunk)
   if res.meta.get('plan'):print('plan',res.meta['plan'],flush=True)
  return res
 def dip(self,c):
  w=self.wells[c-1].copy();w[2]=.024
  self.to([*self.pos[:2],.06],hold=.1)
  self.to([*w[:2],.06]);self.to(w,.04,.35);self.to([*w[:2],.06],.05,.15)
 def stroke(self,pts,z=.014):
  pts=np.array(pts)
  self.to([*pts[0],.045],.12,.2);self.to([*pts[0],z],.04,.2)
  for p in pts[1:]:self.to([*p,z],.035)
  self.to([*pts[-1],z],hold=.15);self.to([*pts[-1],.045],.04,.2)
 def park(self):
  self.to([*self.pos[:2],.08]);self.to([-.3,0,.15],.12,.5);self.flush()
 def photo(self,label):
  self.park();o=r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam']);o.save('/app/output/'+label);return o
